// Generated by scripts/palette.mjs: OKLCH L=0.50, C<=0.11, hues 25° + 36°·i.
// Every swatch gives >= 5.69:1 contrast with white text (WCAG AA), min pairwise ΔE(OK) = 0.059.
export interface Swatch {
  name: string;
  hex: string;
}

export const PALETTE: Swatch[] = [
  { name: 'Crimson', hex: '#984742' },
  { name: 'Amber', hex: '#8f520f' },
  { name: 'Olive', hex: '#746303' },
  { name: 'Forest', hex: '#497029' },
  { name: 'Teal', hex: '#007559' },
  { name: 'Ocean', hex: '#06717a' },
  { name: 'Cobalt', hex: '#126a9c' },
  { name: 'Indigo', hex: '#545ca1' },
  { name: 'Violet', hex: '#794f8f' },
  { name: 'Berry', hex: '#90466d' },
];

export function isHex(value: string): boolean {
  return /^#[0-9a-f]{6}$/i.test(value);
}

function toRgb(hex: string): number[] {
  return [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
}

function toHex(rgb: number[]): string {
  return '#' + rgb.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
}

export function mix(hex: string, other: string, amount: number): string {
  const a = toRgb(hex), b = toRgb(other);
  return toHex(a.map((v, i) => v + (b[i] - v) * amount));
}

function luminance(hex: string): number {
  const [r, g, b] = toRgb(hex).map((v) => {
    v /= 255;
    return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** White text unless the background is too light for it (custom colors only; the palette always gets white). */
export function foregroundFor(hex: string): string {
  return 1.05 / (luminance(hex) + 0.05) >= 4.5 ? '#ffffff' : '#1e1e1e';
}

export function nameOf(hex: string): string {
  return PALETTE.find((s) => s.hex === hex.toLowerCase())?.name ?? hex;
}
